import time


class TokenBucket:
    def __init__(self, rate, capacity, clock=time.monotonic):
        if rate <= 0:
            raise ValueError(f"rate must be positive, got {rate!r}")
        if capacity <= 0:
            raise ValueError(f"capacity must be positive, got {capacity!r}")
        self._rate = rate
        self._capacity = capacity
        self._clock = clock
        self._tokens = float(capacity)
        self._last = clock()

    @property
    def rate(self):
        return self._rate

    @property
    def capacity(self):
        return self._capacity

    @property
    def tokens(self):
        self._refill()
        return self._tokens

    def try_acquire(self, n=1):
        self._check_n(n)
        self._refill()
        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n=1):
        self._check_n(n)
        self._refill()
        if self._tokens >= n:
            return 0.0
        return (n - self._tokens) / self._rate

    def _check_n(self, n):
        if n <= 0 or n > self._capacity:
            raise ValueError(
                f"n must be in (0, capacity={self._capacity}], got {n!r}"
            )

    def _refill(self):
        now = self._clock()
        elapsed = max(0.0, now - self._last)
        self._tokens = min(self._capacity, self._tokens + elapsed * self._rate)
        self._last = now

